// Tenant 128671 mirrors its delivery orders to an external system, and for that
// tenant this button drives that sync rather than the accounting post. A
// selection can mix deliveries at different stages, so each record is sorted
// into the task type it needs and the workflow is called once per task type —
// at most three calls, each carrying its own list of gd ids.
const DO_SYNC_TENANT_ID = "128671";
const DO_SYNC_WORKFLOW_ID = "2076967001969713153";

// posted_status is what tells us whether the external system has already seen
// this delivery, so it decides between sending it out for the first time and
// updating the copy that is already there. A cancelled delivery that was sent
// has to be withdrawn; one that never left is nothing to the external system,
// and neither is a draft.
const getDeliveryOrderTaskType = (item) => {
  const isPosted = item.posted_status?.dict_key === "Posted";

  if (item.gd_status === "Cancelled") {
    return isPosted ? "cancel_do" : null;
  }

  if (item.gd_status === "Created") {
    return isPosted ? "update_do" : "post_do";
  }

  return null;
};

const groupDeliveryOrders = (records) => {
  const groups = { post_do: [], update_do: [], cancel_do: [] };
  const skipped = [];

  records.forEach((item) => {
    const taskType = getDeliveryOrderTaskType(item);

    if (!taskType || !item.id) {
      skipped.push({
        id: item.id,
        gd_no: item.gd_no,
        gd_status: item.gd_status,
        posted_status: item.posted_status?.dict_key,
      });
      return;
    }

    groups[taskType].push(item.id);
  });

  console.log("Delivery order sync — grouped:", groups);

  if (skipped.length > 0) {
    console.log("Delivery order sync — skipped records:", skipped);
  }

  return groups;
};

const syncDeliveryOrders = async (groups) => {
  let organizationId = this.getVarGlobal("deptParentId");
  if (organizationId === "0") {
    organizationId = this.getVarSystem("deptIds").split(",")[0];
  }

  // Sent one task type at a time so a failure on one batch is reported against
  // that batch rather than the whole selection.
  for (const taskType of ["post_do", "update_do", "cancel_do"]) {
    const gdIds = groups[taskType];

    if (gdIds.length === 0) {
      continue;
    }

    console.log(`Delivery order sync — ${taskType}:`, gdIds);

    await this.runWorkflow(
      DO_SYNC_WORKFLOW_ID,
      {
        org_id: organizationId,
        task_type: taskType,
        payload: gdIds,
