// Confirm handler wired to dialog_split_picking's Confirm button.
// Picks up state stashed by ConvertToPicking.js, computes either a single
// "ALL" group (no_split) or N zone-based groups (by_area), then opens
// dialog_assignee for the first group. SplitPickingAssigneeConfirm.js takes
// over from there, walking the user through each group sequentially.

// Subtract authoritative consumed qty (committed picks from Completed TOs +
// in-flight reservations from non-Completed TOs) per (location, batch, HU)
// from the GD line's temp_qty_data. Yields the qty that's still actually
// pickable per source bin. The consumedByLine map is built upstream in
// ConvertToPicking.js (buildConsumedQtyMap) and passed via split_state.
const subtractConsumed = (line, consumedByLine) => {
  let tempArr = [];
  try {
    tempArr = line.temp_qty_data ? JSON.parse(line.temp_qty_data) : [];
  } catch (e) {
    tempArr = [];
  }
  if (!Array.isArray(tempArr) || tempArr.length === 0) return [];

  const consumed = (consumedByLine || {})[String(line.id)] || {};
  const keyOf = (e) =>
    (e.location_id || "no-loc") +
    "_" +
    (e.batch_id || "no-batch") +
    "_" +
    (e.handling_unit_id || "no-hu");

  const remaining = [];
  for (const t of tempArr) {
    const used = consumed[keyOf(t)] || 0;
    const rem = parseFloat(t.gd_quantity || 0) - used;
    if (rem > 0) {
      remaining.push({ ...t, gd_quantity: rem });
    }
  }
  return remaining;
};

// Build a picking-item array for one group, mirroring the grouping +
// HU-header injection logic in GDconvertToPicking.json:code_node_PYFZeGpr.
const buildTablePickingItems = (entries) => {
  const groups = new Map();

  for (const { gd, line, tempItem } of entries) {
    const materialId = String(tempItem.material_id || line.material_id || "");
    const groupKey =
      `${line.id}_${materialId}_` +
      `${tempItem.batch_id || "no-batch"}_` +
      `${tempItem.location_id}_` +
      `${tempItem.handling_unit_id || "no-hu"}`;

    if (!groups.has(groupKey)) {
      groups.set(groupKey, {
        item_code: materialId,
        item_name: line.material_name,
        item_desc: line.gd_material_desc || "",
        remark: line.line_remark_1 || "",
        remark_2: line.line_remark_2 || "",
        remark_3: line.line_remark_3 || "",
        batch_no: tempItem.batch_id ? String(tempItem.batch_id) : null,
        item_batch_id: tempItem.batch_id ? String(tempItem.batch_id) : null,
        qty_to_pick: 0,
        item_uom: String(line.gd_order_uom_id || line.good_delivery_uom_id || ""),
        pending_process_qty: 0,
        source_bin: String(tempItem.location_id),
        line_status: "Open",
        so_no: line.line_so_no,
        gd_no: gd.delivery_no,
        so_id: String(line.line_so_id || ""),
        so_line_id: String(line.so_line_item_id || ""),
        gd_id: String(gd.id),
        gd_line_id: String(line.id),
        serial_numbers: [],
        is_serialized_item: 0,
        handling_unit_id: tempItem.handling_unit_id
          ? String(tempItem.handling_unit_id)
          : null,
      });
    }

    const grp = groups.get(groupKey);
    grp.qty_to_pick += parseFloat(tempItem.gd_quantity || 0);
    grp.pending_process_qty += parseFloat(tempItem.gd_quantity || 0);
    if (tempItem.serial_number) {
      grp.serial_numbers.push(String(tempItem.serial_number));
      grp.is_serialized_item = 1;
    }
  }

  let items = [];
  for (const grp of groups.values()) {
    if (grp.serial_numbers.length > 0) {
      grp.serial_numbers = grp.serial_numbers.join(", ");
    } else {
      delete grp.serial_numbers;
    }
    items.push(grp);
  }

  // HU header sort + injection (matches GDconvertToPicking.json behavior)
  items.sort((a, b) => {
    if (a.gd_line_id !== b.gd_line_id) return 0;
    const aHU = a.handling_unit_id || "";
    const bHU = b.handling_unit_id || "";
    if (aHU === bHU) return 0;
    return aHU < bHU ? -1 : 1;
  });

  const withHeaders = [];
  let lastHuId = null;
  for (const row of items) {
    const huId = row.handling_unit_id;
    if (huId && huId !== lastHuId) {
      withHeaders.push({
        row_type: "header",
        handling_unit_id: huId,
        hu_select: 0,
      });
      lastHuId = huId;
    } else if (!huId) {
      lastHuId = null;
    }
    withHeaders.push({ ...row, row_type: "item" });
  }
  return withHeaders;
};

(async () => {
  try {
    const splitMode = await this.getValue("dialog_split_picking.split");
    const tierLevel = await this.getValue("dialog_split_picking.tier_level");

    const stateRaw = await this.getValue("split_state");
    const state = stateRaw ? JSON.parse(stateRaw) : {};
    const gdIds = Array.isArray(state.gd_ids) ? state.gd_ids : [];
    const consumedByLine = state.consumed_by_line || {};

    if (gdIds.length === 0) {
      this.$message.error("No goods deliveries selected.");
      return;
    }

    this.showLoading("Computing picking groups...");

    // 1. Re-fetch full GD documents (selectedRecords from list view may not
    //    carry temp_qty_data / picked_temp_qty_data on each line).
    const gdIdsClean = gdIds.map((id) => String(id)).filter(Boolean);
    if (gdIdsClean.length === 0) {
      this.hideLoading();
      this.$message.error("No valid goods delivery IDs.");
      return;
    }
    const gdResult = await db
      .collection("goods_delivery")
      .filter([
        {
          type: "branch",
          operator: "all",
          children: [
            {
              prop: "id",
              operator: "in",
              value: gdIdsClean,
            },
          ],
        },
      ])
      .get();
    const gds = gdResult?.data || [];
    if (gds.length === 0) {
      this.hideLoading();
      this.$message.error("Could not fetch selected goods deliveries.");
      return;
    }

    // 2. Per line, compute remaining tempItems (subtract cumulative picked).
    //    Skip lines where remaining is empty or terminal status.
    const entries = []; // each: { gd, line, tempItem }
    for (const gd of gds) {
      for (const line of gd.table_gd || []) {
        if (!line.material_id) continue;
        if (line.picking_status === "Completed") continue;
        if (line.picking_status === "Cancelled") continue;

        const remaining = subtractConsumed(line, consumedByLine);
        for (const tempItem of remaining) {
          entries.push({ gd, line, tempItem });
        }
      }
    }

    if (entries.length === 0) {
      this.hideLoading();
      this.$message.error("No remaining quantity to pick on the selected GDs.");
      return;
    }

    // 3. Build groups.
    const groups = []; // each: { key, entries }

    if (splitMode === "by_area") {
      const tierNum = String(tierLevel || "").replace(/^tier_/, "");
      if (!tierNum || !["1", "2", "3", "4", "5"].includes(tierNum)) {
        this.hideLoading();
        this.$message.error("Invalid tier level.");
        return;
      }
      const tierCodeField = `bin_code_tier_${tierNum}`;
      const tierActiveField = `tier_${tierNum}_active`;

      // Group on the full bin path THROUGH the chosen tier, not the bare code
      // at it. Codes below tier 1 are relative labels — "L", "GF", "Middle" —
      // reused under many parents, so the bare code merged bins in different
      // buildings into one picking task ("L" alone covers 4 different lots).
      // Mirrors bin_location.onChange_tier_code_change, which builds
      // bin_location_combine the same way: tier 1 always, deeper tiers when
      // active, joined by "-". Verified to reproduce it for every bin.
      const tierPathOf = (bin) => {
        const parts = [];
        for (let t = 1; t <= Number(tierNum); t++) {
          if (t === 1 || bin[`tier_${t}_active`]) {
            parts.push(bin[`bin_code_tier_${t}`] || "");
          }
        }
        return parts.join("-");
      };

      const locationIds = [
        ...new Set(
          entries.map((e) => e.tempItem.location_id).filter(Boolean),
        ),
      ];
      const binResult = await db
        .collection("bin_location")
        .filter([
          {
            type: "branch",
            operator: "all",
            children: [
              {
                prop: "id",
                operator: "in",
                value: locationIds.map((id) => String(id)),
              },
            ],
          },
        ])
        .get();
      const binByLoc = {};
      for (const bin of binResult?.data || []) {
        binByLoc[bin.id] = bin;
      }

      // An entry whose bin is missing, has the chosen tier inactive, or has a
      // blank code on it still has to be picked. Rather than dropping it —
      // which strands the GD line at "Not Created" while Packing (built from
      // the full GD allocation) still shows it, as GD-20260827-090 did with 2
      // of 3 lines — it falls back to its own bin, one group per bin location.
      const binLabelOf = (bin, locationId) =>
        (bin && (bin.bin_location_combine || bin.bin_name)) || String(locationId);

      // Kept apart from `grouped` so a fallback bin label that happens to equal
      // some zoned bin's path still gets its own picking task.
      const grouped = new Map();
      const byBin = new Map();
      const skipped = [];
      for (const entry of entries) {
        const locationId = entry.tempItem.location_id;
        const bin = binByLoc[locationId];
        let tierPath = null;
        if (!bin) {
          skipped.push({ entry, reason: "bin not found" });
        } else if (bin[tierActiveField] !== 1) {
          skipped.push({ entry, reason: `${tierActiveField} is not active` });
        } else if (!bin[tierCodeField]) {
          skipped.push({ entry, reason: `${tierCodeField} is empty` });
        } else {
          tierPath = tierPathOf(bin);
        }

        if (!tierPath) {
          const binKey = String(locationId);
          if (!byBin.has(binKey)) {
            byBin.set(binKey, { label: binLabelOf(bin, locationId), entries: [] });
          }
          byBin.get(binKey).entries.push(entry);
          continue;
        }
        if (!grouped.has(tierPath)) grouped.set(tierPath, []);
        grouped.get(tierPath).push(entry);
      }

      if (skipped.length > 0) {
        console.warn(
          `Grouped ${skipped.length} item(s) by bin location — no valid ${tierCodeField}:`,
          skipped,
        );
      }

      for (const [tierPath, groupEntries] of grouped.entries()) {
        groups.push({ key: tierPath, entries: groupEntries });
      }
      // Last and name-ordered, so the user assigns the real zones first and
      // walks the per-bin leftovers in a predictable order.
      const binGroups = [...byBin.values()].sort((a, b) =>
        a.label < b.label ? -1 : a.label > b.label ? 1 : 0,
      );
      for (const g of binGroups) {
        groups.push({ key: g.label, entries: g.entries });
      }
    } else {
      // no_split (default)
      groups.push({ key: "All", entries });
    }

    // 4. Build picking-item array per group.
    const groupPayloads = groups.map((g) => {
      const tablePickingItems = buildTablePickingItems(g.entries);

      // Aggregate header fields from contributing GDs.
      const gdsInGroup = [
        ...new Map(g.entries.map((e) => [e.gd.id, e.gd])).values(),
      ];
      const gdNoArr = gdsInGroup.map((gd) => String(gd.id));
      const deliveryNo = gdsInGroup.map((gd) => gd.delivery_no).join(", ");
      const soNos = [
        ...new Set(
          tablePickingItems
            .filter((r) => r.row_type !== "header")
            .map((r) => r.so_no)
            .filter(Boolean),
        ),
      ].join(", ");
      const customerIds = [
        ...new Set(gdsInGroup.map((gd) => gd.customer_name).filter(Boolean)),
      ];
      const refDoc = gdsInGroup[0]?.gd_ref_doc || "";
      // Header remarks follow the single-source rule the convert workflows use:
      // a group spanning several GDs makes the attribution ambiguous.
      const onlyGd = gdsInGroup.length === 1 ? gdsInGroup[0] : null;

      return {
        key: g.key,
        gd_ids: gdNoArr,
        remarks: onlyGd ? onlyGd.order_remark || "" : "",
        remarks_2: onlyGd ? onlyGd.order_remark2 || "" : "",
        remarks_3: onlyGd ? onlyGd.order_remark3 || "" : "",
        delivery_no: deliveryNo,
        so_no: soNos,
        customer_id: customerIds,
        ref_doc: refDoc,
        table_picking_items: tablePickingItems,
      };
    });

    // 5. Persist groups + reset index/assignees, then open dialog_assignee
    //    for the first group.
    state.groups = groupPayloads;
    state.index = 0;
    state.assignees = [];
    await this.setData({
      split_state: JSON.stringify(state),
      "dialog_assignee.area_name": groupPayloads[0].key,
      "dialog_assignee.assignee": [],
      // Re-stamped in case the dialog was reopened without going through the
      // bulk action again; the plant cannot change mid-run.
      "dialog_assignee.plant_id": state.plant_id || "",
    });

    this.hideLoading();
    await this.closeDialog("dialog_split_picking");
    await this.openDialog("dialog_assignee");
  } catch (error) {
    this.hideLoading();
    console.error("SplitPickingConfirm error:", error);
    this.$message.error(error.message || "Failed to compute picking groups.");
  }
})();

// Confirm handler wired to dialog_assignee's Confirm button.
// Captures the assignee for the current group, then either advances to the
// next group (re-populating the dialog) or, on the last group, runs the
// finalize routine: create N transfer_orders, update affected GDs, refresh
// the list. State lives on form-level hidden fields populated by
// ConvertToPicking.js / SplitPickingConfirm.js.

const getPickingNoType = async (organizationId) => {
  try {
    const res = await db
      .collection("su_code_serial_no_rule")
      .where({
        department_id: organizationId,
        business_type: "Picking",
        is_default: 1,
      })
      .get();
    return res?.data?.[0]?.id || null;
  } catch (err) {
    console.error("Error reading picking prefix:", err);
    return null;
  }
};

// Build N picking payloads (one per group) and run PickingLoopWorkflow with
// arrayData. The workflow handles: prefix generation (to_id auto-fill),
// required-field validation, the actual transfer_order add, and the GD
// picking_status writeback (only bumps Not Created / null lines to Created;
// leaves In Progress / Completed alone — M:N safe).
const finalize = async (
  groups,
  assignees,
  plantId,
  organizationId,
  listComponentId,
) => {
  const pickingNoType = await getPickingNoType(organizationId);
  const nowMysql = new Date().toISOString().slice(0, 19).replace("T", " ");
  const createdBy =
    typeof this !== "undefined" && this.getVarGlobal
      ? this.getVarGlobal("nickname")
      : "";

  const arrayData = groups.map((group, i) => {
    const assignee = assignees[i] || [];
    return {
      to_status: "Created",
      to_id: "",
      to_id_type: pickingNoType,
      plant_id: plantId,
      organization_id: organizationId,
      movement_type: "Picking",
      ref_doc_type: "Goods Delivery",
      gd_no: group.gd_ids,
      delivery_no: group.delivery_no,
      so_no: group.so_no,
      customer_id: group.customer_id,
      ref_doc: group.ref_doc,
      // Zone/area code the group was split on ("All" when split=no_split);
      // same value dialog_assignee.area_name shows read-only for this group.
      area_name: group.key,
      assigned_to: Array.isArray(assignee) ? assignee : [assignee],
      table_picking_items: group.table_picking_items,
      created_by: createdBy,
      created_at: nowMysql,
      remarks: group.remarks || "",
      remarks_2: group.remarks_2 || "",
      remarks_3: group.remarks_3 || "",
      to_no: [],
      table_picking_records: [],
      is_processing: 0,
    };
  });

  let workflowResult;
  await this.runWorkflow(
    "2021065804251615233",
    { arrayData, saveAs: "Created", pageStatus: "Add" },
    (res) => {
      workflowResult = res;
    },
    (err) => {
      console.error("Picking workflow error:", err);
      workflowResult = err;
    },
  );

  if (!workflowResult || !workflowResult.data) {
    this.$message.error("No response from picking workflow");
    return;
  }

  const code = workflowResult.data.code;
  if (code === "400" || code === 400 || workflowResult.data.success === false) {
    const msg =
      workflowResult.data.msg ||
      workflowResult.data.message ||
      "Failed to create pickings";
    this.$message.error(msg);
    return;
  }

  if (code === "200" || code === 200 || workflowResult.data.success === true) {
    this.$message.success(
      `Successfully created ${groups.length} picking record(s).`,
    );
    if (listComponentId) {
      try {
        this.getComponent(listComponentId)?.$refs?.crud?.clearSelection?.();
      } catch (e) {
        // ignore
      }
    }
    this.refresh && this.refresh();
  } else {
    this.$message.error("Unknown workflow status");
  }
};

(async () => {
  try {
    const stateRaw = await this.getValue("split_state");
    const state = stateRaw ? JSON.parse(stateRaw) : {};
    const groups = Array.isArray(state.groups) ? state.groups : [];
    let index = Number.isFinite(state.index) ? state.index : 0;
    const assignees = Array.isArray(state.assignees) ? state.assignees : [];

    if (groups.length === 0) {
      this.$message.error(
        "No picking groups found. Please restart the conversion.",
      );
      await this.closeDialog("dialog_assignee");
      return;
    }

    // Assignee is optional — empty = unassigned picking.
    const rawAssignee = await this.getValue("dialog_assignee.assignee");
    const currentAssignee = Array.isArray(rawAssignee)
      ? rawAssignee
      : rawAssignee
        ? [rawAssignee]
        : [];

    assignees[index] = currentAssignee;
    const nextIndex = index + 1;

    if (nextIndex < groups.length) {
      // Advance to next group: persist state, repopulate dialog, keep open.
      state.assignees = assignees;
      state.index = nextIndex;
      await this.setData({
        split_state: JSON.stringify(state),
        "dialog_assignee.area_name": groups[nextIndex].key,
        "dialog_assignee.assignee": [],
      });
      // Dialog is already open; setData refreshes its visible state.
    } else {
      // Last group — finalize.
      state.assignees = assignees;
      await this.setData({ split_state: JSON.stringify(state) });

      const plantId = state.plant_id || "";
      const organizationId = state.organization_id || "";
      const listComponentId = state.list_component_id || "";

      await this.closeDialog("dialog_assignee");
      this.showLoading("Creating pickings...");
      try {
        await finalize(
          groups,
          assignees,
          plantId,
          organizationId,
          listComponentId,
        );
      } finally {
        this.hideLoading();
        // Clear state for next run.
        await this.setData({
          split_state: "",
        });
      }
    }
  } catch (error) {
    console.error("SplitPickingAssigneeConfirm error:", error);
    this.$message.error(
      error.message || "Failed to assign and create pickings.",
    );
  }
})();

const REVERT_WORKFLOW_ID = "2058819647368241153";

const runRevertWorkflow = async (data) => {
  return new Promise((resolve, reject) => {
    this.runWorkflow(
      REVERT_WORKFLOW_ID,
      {
        allData: data,
        pageStatus: "Edit",
      },
      (res) => {
        console.log("GD revert workflow response:", res);
        resolve(res);
      },
      (err) => {
        console.error("Failed to revert Goods Delivery:", err);
        reject(err);
      },
    );
  });
};

// A Goods Delivery carries si_status = "" / null (not invoiced), "Partially
// Invoiced", "Fully Invoiced" or "Cancelled". Anything other than empty or
// "Cancelled" means a live Sales Invoice exists against this GD, so the
// delivery cannot be rolled back until that invoice is cancelled.
const isInvoiced = (record) => {
  const status = String((record && record.si_status) || "").trim();
  return status !== "" && status.toLowerCase() !== "cancelled";
};

const describeInvoiced = (records) =>
  records
    .map((item) => `${item.delivery_no} (${item.si_status})`)
    .join("<br>");

const invoicedError = (siStatus) =>
  `Already invoiced (${siStatus}). Please cancel the sales invoice first.`;

const handleWorkflowResult = (workflowResult, gdItem) => {
  if (!workflowResult || !workflowResult.data) {
    return {
      delivery_no: gdItem.delivery_no,
      success: false,
      error: "No response from revert workflow",
    };
  }

  const resultCode = workflowResult.data.code;

  // 409 - Conflict (state changed since completion; cannot safely revert)
  if (resultCode === "409" || resultCode === 409) {
    return {
      delivery_no: gdItem.delivery_no,
      success: false,
      error:
        workflowResult.data.msg ||
        workflowResult.data.message ||
        "Conflict: state has changed since completion",
    };
  }

  // 400 - general error (not Completed, snapshot missing, etc.)
  if (
    resultCode === "400" ||
    resultCode === 400 ||
    workflowResult.data.success === false
  ) {
    return {
      delivery_no: gdItem.delivery_no,
      success: false,
      error:
        workflowResult.data.msg ||
        workflowResult.data.message ||
        "Failed to revert Goods Delivery",
    };
  }

  // 200 - success
  if (
    resultCode === "200" ||
    resultCode === 200 ||
    workflowResult.data.success === true
  ) {
    return {
      delivery_no: gdItem.delivery_no,
      success: true,
    };
  }

  return {
    delivery_no: gdItem.delivery_no,
    success: false,
    error: "Unknown revert workflow status",
  };
};

(async () => {
  try {
    this.showLoading();
    const allListID = "custom_ezwb0qqp";

    const selectedRecords = this.getComponent(allListID)?.$refs.crud.tableSelect;

    console.log("selectedRecords", selectedRecords);

    if (!selectedRecords || selectedRecords.length === 0) {
      this.hideLoading();
      this.$message.error("Please select at least one record.");
      return;
    }

    const completedGoodsDelivery = selectedRecords.filter(
      (item) => item.gd_status === "Completed",
    );

    if (completedGoodsDelivery.length === 0) {
      this.hideLoading();
      this.$message.error(
        "Please select at least one completed goods delivery to revert.",
      );
      return;
    }

    // Invoiced goods deliveries cannot be reverted - the sales invoice has to
    // be cancelled first, which resets si_status back to empty.
    const invoicedGoodsDelivery = completedGoodsDelivery.filter(isInvoiced);
    const goodsDeliveryData = completedGoodsDelivery.filter(
      (item) => !isInvoiced(item),
    );

    if (goodsDeliveryData.length === 0) {
      this.hideLoading();
      this.$message({
        type: "error",
        message: `The selected goods delivery(s) have already been invoiced and cannot be reverted. Please cancel the sales invoice first.<br>${describeInvoiced(
          invoicedGoodsDelivery,
        )}`,
        dangerouslyUseHTMLString: true,
      });
      return;
    }

    const goodsDeliveryNumbers = goodsDeliveryData.map(
      (item) => item.delivery_no,
    );

    const skippedNote =
      invoicedGoodsDelivery.length > 0
        ? `<br><br><strong>${
            invoicedGoodsDelivery.length
          } invoiced goods delivery(s) will be skipped:</strong> <br>${describeInvoiced(
            invoicedGoodsDelivery,
          )}<br>Please cancel the sales invoice first to revert them.`
        : "";

    await this.$confirm(
      `You've selected ${
        goodsDeliveryNumbers.length
      } goods delivery(s) to revert to Created. This will undo inventory delivery, stock movements, handling unit deductions, and Sales Order updates. <br> <strong>Goods Delivery Numbers:</strong> <br>${goodsDeliveryNumbers.join(
        ", ",
      )}${skippedNote} <br>Do you want to proceed?`,
      "Revert Goods Delivery to Created",
      {
        confirmButtonText: "Revert",
        cancelButtonText: "Cancel",
        type: "warning",
        dangerouslyUseHTMLString: true,
      },
    ).catch(() => {
      console.log("User clicked Cancel or closed the dialog");
      throw new Error();
    });

    const results = invoicedGoodsDelivery.map((item) => ({
      delivery_no: item.delivery_no,
      success: false,
      error: invoicedError(item.si_status),
    }));

    for (const gdItem of goodsDeliveryData) {
      const id = gdItem.id;

      const data = await db.collection("goods_delivery").doc(id).get();

      if (!data.data || data.data.length === 0) {
        results.push({
          delivery_no: gdItem.delivery_no,
          success: false,
          error: "Goods Delivery record not found",
        });
        continue;
      }

      try {
        const gdData = data.data[0];

        // The selected row can be stale if the goods delivery was invoiced
        // elsewhere after the list was loaded. The record is already fetched,
        // so re-checking here costs nothing.
        if (isInvoiced(gdData)) {
          results.push({
            delivery_no: gdItem.delivery_no,
            success: false,
            error: invoicedError(gdData.si_status),
          });
          continue;
        }

        const workflowResult = await runRevertWorkflow(gdData);
        const result = handleWorkflowResult(workflowResult, gdItem);
        results.push(result);
      } catch (error) {
        results.push({
          delivery_no: gdItem.delivery_no,
          success: false,
          error: error.message || "Failed to revert",
        });
      }
    }

    // Show summary
    const successCount = results.filter((r) => r.success).length;
    const failCount = results.filter((r) => !r.success).length;

    if (failCount > 0) {
      const failedItems = results
        .filter((r) => !r.success)
        .map((r) => `${r.delivery_no}: ${r.error}`)
        .join("<br>");
      this.$message({
        type: "error",
        message: `${successCount} reverted, ${failCount} failed:<br>${failedItems}`,
        dangerouslyUseHTMLString: true,
      });
    } else {
      this.$message.success(
        `All ${successCount} Goods Delivery reverted to Created successfully`,
      );
    }

    this.hideLoading();
    this.refresh();
  } catch (error) {
    this.hideLoading();
    console.error(error);
  }
})();

// autoPi: "" (not decided yet) | "confirmed" | "skip". Once decided it is threaded through the
// 401/403 retries below so the user is never asked the same question twice.
const handleConvertSI = async (
  selectedRecords,
  convertTo,
  isMultiple,
  filterDraft,
  autoPi,
) => {
  const gdIds = [...new Set(selectedRecords.map((r) => r.id))];

  // Internal trading = the GD is the source of a "Linked" GD->GR row in document_linkage.
  // Two separate checks need that fact, so read it once:
  //   - the mix guard, only when building ONE SI out of 2+ GDs
  //   - the Purchase Invoice confirm, only when completing (see below)
  const needsMixGuard = isMultiple === "single" && selectedRecords.length > 1;
  const needsPiAnswer = convertTo === "completed" && !autoPi;

  let internalCount = 0;
  if (needsMixGuard || needsPiAnswer) {
    const linkRes = await db
      .collection("document_linkage")
      .filter([
        {
          type: "branch",
          operator: "all",
          children: [
            {
              prop: "source_doc_type",
              operator: "equal",
              value: "Goods Delivery",
            },
            { prop: "source_doc_id", operator: "in", value: gdIds },
            { prop: "link_status", operator: "equal", value: "Linked" },
          ],
        },
      ])
      .get();

    const internalSet = new Set(
      (linkRes?.data || []).map((r) => r.source_doc_id),
    );
    internalCount = gdIds.filter((id) => internalSet.has(id)).length;
  }

  // Block combining internal-trading and non-internal Goods Deliveries into ONE
  // Sales Invoice. "multiple" gives each GD its own SI, so there is no mix to block.
  if (needsMixGuard && internalCount > 0 && internalCount < gdIds.length) {
    await this.$alert(
      "Cannot combine internal trading and non-internal Goods Deliveries in the same Sales Invoice. Please select only one type, or convert to multiple Sales Invoices.",
      "Error",
      { confirmButtonText: "OK", type: "error" },
    );
    return;
  }

  // SI_SAVE will not write an internal-trading COMPLETED invoice until it is told whether to also
  // create the buyer organization's Purchase Invoice -- it returns pi_confirm 411 and saves
  // nothing. The SI form answers that (SIsaveAsCompleted.js); this path never did, so completing
  // an internal GD silently produced no invoice at all while still reporting success. Ask here and
  // pass the answer through. (Draft never arms the gate, so it is only asked when completing.)
  if (needsPiAnswer) {
    if (internalCount > 0) {
      const proceed = await this.$confirm(
        `${internalCount} of the selected Goods Delivery(s) are linked to internal Purchase Orders.<br><br>Auto-create the Purchase Invoice in the buyer organization?`,
        "Internal Trading – Auto-create Purchase Invoice",
        {
          confirmButtonText: "Yes, create PI",
          cancelButtonText: "No, invoice only",
          type: "info",
          dangerouslyUseHTMLString: true,
        },
      )
        .then(() => true)
        .catch(() => false);

      autoPi = proceed ? "confirmed" : "skip";
    } else {
      // Nothing internal — the gate never arms. Memoised so a retry does not re-query.
      autoPi = "skip";
    }
  }

  this.showLoading("Converting Goods Delivery to Sales Invoice...");
  await this.runWorkflow(
    "2070069049332416514",
    {
      ids: selectedRecords.map((record) => record.id),
      convert_to: convertTo,
      is_multiple: isMultiple,
      filter_draft: filterDraft,
      auto_pi: autoPi || "",
    },
    async (res) => {
      console.log("SI Data", res.data);
      this.$alert(
        "Convert Goods Delivery to Sales Invoice Success",
        "Success",
        {
          confirmButtonText: "OK",
          type: "success",
        },
      );
      this.refresh();
      this.hideLoading();
    },
    async (err) => {
      console.error(err);
      this.hideLoading();
      if (err.data?.code === 401) {
        // Draft SO cannot be converted.
        await this.$confirm(err.data.msg, "GD cannot be converted.", {
          confirmButtonText: "Proceed",
          type: "warning",
          dangerouslyUseHTMLString: true,
        }).catch(() => {
          console.log("User clicked Cancel or closed the dialog");
          this.hideLoading();
          throw new Error("Converting sales invoice cancelled.");
        });

        await handleConvertSI(
          selectedRecords,
          convertTo,
          isMultiple,
          "yes",
          autoPi,
        );
      } else if (err.data?.code === 402) {
        // Selected Goods Delivery(s) already has a related Sales Invoice and cannot be converted.
        await this.$alert(err.data.msg, "Error", {
          confirmButtonText: "OK",
          type: "error",
        });
      } else if (err.data?.code === 403) {
        // All selected Goods Delivery(s) must be from the same plant/organization to create a single Sales Invoice.
        await this.$confirm(err.data.msg, "", {
          confirmButtonText: "Convert to Multiple SI",
          type: "warning",
          dangerouslyUseHTMLString: true,
        }).catch(() => {
          console.log("User clicked Cancel or closed the dialog");
          this.hideLoading();
          throw new Error("Converting sales invoice cancelled.");
        });

        await handleConvertSI(
          selectedRecords,
          convertTo,
          "multiple",
          filterDraft,
          autoPi,
        );
      }
    },
  );
  this.hideLoading();
};

